from .parser import rows

_QTY = "0123456789"


def _valid_qty(value):
    return bool(value) and all(char in _QTY for char in value)


def import_text(text, store):
    report = {'seen': 0, 'imported': 0, 'rejected': 0, 'quantity': 0}
    for parts in rows(text):
        report['seen'] += 1
        parts = [part.strip() for part in parts]
        if len(parts) != 3 or not parts[0] or not parts[1]:
            report['rejected'] += 1
            continue
        if not _valid_qty(parts[2]):
            report['rejected'] += 1
            continue
        store.put(parts[0], parts[1], int(parts[2], 10))
        report['imported'] += 1
        report['quantity'] += int(parts[2], 10)
    return report

